-- ============================================================================
--  ACADOCS — mock data for every table (37 tables)
--  Import AFTER acadocs_schema_cleaned.sql, into the empty `acadocs` database.
--
--  Logins (password for every account: Password123!)
--    Principal (admin) : principal@mnhs.edu.ph
--    ADAS              : adas@mnhs.edu.ph
--    Teachers (10)     : maria.santos@, jose.reyes@, ana.cruz@, mark.delacruz@,
--                        grace.ramos@, paolo.garcia@, jasmine.aquino@,
--                        ramon.castillo@, kristine.navarro@, edwin.flores@  (all @mnhs.edu.ph)
--
--  What's inside
--    - 10 school years of KPI data (SY 2017-2018 to SY 2026-2027): DepEd KPI
--      reports, enrollment per grade level (monthly for the 3 latest years),
--      MPS per grade level / subject / term, raw per-section test scores for
--      the 2 latest years, KPI snapshots
--    - Time records for every working day from Jun 15 to Oct 1, 2026 (12 staff
--      accounts + 2 scanner-only staff), with holidays
--    - Tasks (teacher / ADAS / specific people), submissions with files,
--      review status, feedback, document folders; legacy documents
--    - Announcements, notifications, chat (groups, direct, replies, reactions,
--      a shared announcement), document links, templates, property inventory,
--      parent meetings, DepEd documents, plus one sample password reset / API token
--    - migrations rows, so `php spark migrate` sees the schema as up to date
--
--  Files: templates and submitted files point at sample files that ship with
--  the project (app/Templates, trainee-data/, public/assets/img) — Word, Excel and images only, no PowerPoint — so preview
--  and download work out of the box.
--  Generated: 2026-10-02
-- ============================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
START TRANSACTION;
USE `acadocs`;

