-- announcements (12 rows)
INSERT INTO `announcements` (`id`, `type`, `title`, `content`, `image`, `date`, `status`, `created_by`, `created_at`) VALUES
(1, 'Announcement', 'Opening of Classes — SY 2026-2027', 'Classes for SY 2026-2027 officially start on **June 15, 2026**. Advisers, please be in your rooms by 6:45 AM.', NULL, '2026-06-10', 'active', 1, '2026-06-09 16:30:00'),
(2, 'Announcement', 'Brigada Eskwela 2026', 'Brigada Eskwela runs **June 1–6**. Coordinate with your grade-level chair for room assignments.', NULL, '2026-05-28', 'active', 1, '2026-05-27 16:30:00'),
(3, 'Forms', 'Updated School Forms (SF1–SF10)', 'The updated DepEd school forms are now in **Templates → School Forms**. Use these starting this quarter.', NULL, '2026-06-18', 'active', 2, '2026-06-17 16:30:00'),
(4, 'Announcement', 'Faculty Meeting — July 3', 'General faculty meeting on **Friday, July 3, 3:00 PM** at the AVR. Agenda: Q1 targets, LIS updating, Brigada report.', NULL, '2026-07-01', 'active', 1, '2026-06-30 16:30:00'),
(5, 'Questionnaires', 'Teacher Wellness Survey', 'Please answer the short wellness survey before **July 31**. Responses are anonymous.', NULL, '2026-07-15', 'active', 2, '2026-07-14 16:30:00'),
(6, 'Announcement', 'Nutrition Month Celebration', 'Nutrition Month culminating program on **July 30**. Each section prepares one healthy-recipe booth.', NULL, '2026-07-20', 'active', 1, '2026-07-19 16:30:00'),
(7, 'Forms', 'Leave Application Form (CS Form 6)', 'Leave applications must be filed at least 5 days ahead using CS Form 6, available from the ADAS office.', NULL, '2026-08-03', 'active', 2, '2026-08-02 16:30:00'),
(8, 'Announcement', 'Q1 Examination Schedule', 'First quarter examinations: **August 26–28**. Submit test questionnaires to your department head by August 19.', NULL, '2026-08-12', 'active', 1, '2026-08-11 16:30:00'),
(9, 'Announcement', 'Buwan ng Wika Program', 'Buwan ng Wika culminating activity on **August 28**. Filipino department in charge.', NULL, '2026-08-18', 'active', 1, '2026-08-17 16:30:00'),
(10, 'Questionnaires', 'LAC Session Topic Survey', 'Vote for the Learning Action Cell topics for the second quarter.', NULL, '2026-09-07', 'active', 2, '2026-09-06 16:30:00'),
(11, 'Announcement', 'Parent-Teacher Conference — Q1 Cards', 'Distribution of Q1 report cards and parent conference on **October 9, 1:00 PM**.', NULL, '2026-09-29', 'active', 1, '2026-09-28 16:30:00'),
(12, 'Announcement', 'Science Fair 2026', 'School science fair on **October 23**. Science teachers will coordinate investigatory project entries.', NULL, '2026-10-01', 'active', 1, '2026-09-30 16:30:00');

