(6, 'Q2 DLL (Weeks 1–2)', 'Daily Lesson Logs for the first two weeks of the second quarter.', 'teacher', '2026-10-16', 'Open', 'Ricardo M. Villanueva', '2026-09-28 09:30:00'),
(7, 'Property Inventory Report', 'Consolidated school property inventory with condition status per room.', 'adas', '2026-08-20', 'Closed', 'Ricardo M. Villanueva', '2026-08-03 09:30:00'),
(8, 'Monthly Attendance Summary (Staff)', 'Summary of staff attendance from the biometric logs for September.', 'adas', '2026-10-09', 'Open', 'Ricardo M. Villanueva', '2026-09-28 09:30:00'),
(9, 'Brigada Eskwela Accomplishment Report', 'Photos and narrative report of Brigada Eskwela activities in your advisory room.', 'specific', '2026-06-19', 'Closed', 'Ricardo M. Villanueva', '2026-06-01 09:30:00'),
(10, 'Science Fair Coordinators\' Plan', 'Activity plan, timeline and budget for the school science fair.', 'specific', '2026-10-12', 'Open', 'Ricardo M. Villanueva', '2026-09-15 09:30:00');

