-- messages (19 rows)
INSERT INTO `messages` (`id`, `conversation_id`, `sender_id`, `reply_to_id`, `body`, `attachment_path`, `attachment_name`, `attachment_ext`, `announcement_id`, `created_at`, `edited_at`, `deleted_at`) VALUES
(1, 1, 1, NULL, 'Good morning, everyone! Welcome to SY 2026-2027. This group is for official faculty announcements.', NULL, NULL, NULL, NULL, '2026-06-08 08:05:00', NULL, NULL),
(2, 1, 3, 1, 'Good morning, Sir! Thank you po.', NULL, NULL, NULL, NULL, '2026-06-08 08:12:00', NULL, NULL),
(3, 1, 2, NULL, 'Reminder: please submit your advisory lists to the ADAS office by Friday.', NULL, NULL, NULL, NULL, '2026-06-16 09:00:00', NULL, NULL),
(4, 1, 6, 3, 'Noted po, Ma\'am Liza.', NULL, NULL, NULL, NULL, '2026-06-16 09:04:00', NULL, NULL),
(5, 1, 1, NULL, '📢 Faculty Meeting — July 3', NULL, NULL, NULL, 4, '2026-07-01 16:40:00', NULL, NULL),
(6, 1, 9, 5, 'Will the meeting be in the AVR or the library?', NULL, NULL, NULL, NULL, '2026-07-01 17:02:00', NULL, NULL),
(7, 1, 1, 6, 'AVR po. Thank you.', NULL, NULL, NULL, NULL, '2026-07-01 17:05:00', '2026-07-01 17:06:00', NULL),
(8, 1, 2, NULL, 'Q1 exam questionnaires are due to department heads on August 19.', NULL, NULL, NULL, NULL, '2026-08-12 10:30:00', NULL, NULL),
(9, 1, 1, NULL, '📢 Parent-Teacher Conference — Q1 Cards

Advisers, please prepare the report cards ahead of time.', NULL, NULL, NULL, 11, '2026-09-29 15:10:00', NULL, NULL),
(10, 2, 1, NULL, 'Grade 7 advisers, please consolidate your SF2 for July.', NULL, NULL, NULL, NULL, '2026-07-27 08:30:00', NULL, NULL),
(11, 2, 4, 10, 'Mabini is done, Sir. Uploading now.', NULL, NULL, NULL, NULL, '2026-07-28 14:20:00', NULL, NULL),
(12, 2, 5, 10, 'Rizal will follow tomorrow po.', NULL, NULL, NULL, NULL, '2026-07-28 15:45:00', NULL, NULL),
(13, 2, 3, NULL, 'Bonifacio submitted na po.', NULL, NULL, NULL, NULL, '2026-07-29 09:10:00', NULL, NULL),
(14, 3, 1, NULL, 'Ma\'am Maria, your Q1 DLL was very well organized. Can you share your template with the English department?', NULL, NULL, NULL, NULL, '2026-07-12 11:00:00', NULL, NULL),
(15, 3, 3, 14, 'Of course, Sir! I\'ll send it to the group today.', NULL, NULL, NULL, NULL, '2026-07-12 11:15:00', NULL, NULL),
(16, 4, 2, NULL, 'Sir Paolo, your biometric shows no time-out last Tuesday. Please file the correction form.', NULL, NULL, NULL, NULL, '2026-08-05 13:05:00', NULL, NULL),
(17, 4, 8, 16, 'Sorry po, I forgot to tap out. I\'ll file it today.', NULL, NULL, NULL, NULL, '2026-08-05 13:20:00', NULL, NULL),
(18, 5, 5, NULL, 'Grace, are we still using the old item analysis sheet for Q2?', NULL, NULL, NULL, NULL, '2026-09-01 15:00:00', NULL, NULL),
(19, 5, 9, 18, 'Use the one in Document Links — it computes the MPS automatically.', NULL, NULL, NULL, NULL, '2026-09-01 15:12:00', NULL, NULL);

